import{z as d,x as A,o as l,c as p,q as t,j as i,D as r,d as n,s as E,S as s,b as e}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"分支定界与整数规划","description":"","frontmatter":{"title":"分支定界与整数规划","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/branch-and-bound.md","filePath":"cs/branch-and-bound.md","lastUpdated":1791063341000}'),B={name:"cs/branch-and-bound.md"};function P(m,a,D,C,u,h){const o=A("Mermaid");return l(),p("div",null,[a[2]||(a[2]=t('<h1 id="分支定界与整数规划" tabindex="-1">分支定界与整数规划 <a class="header-anchor" href="#分支定界与整数规划" aria-label="Permalink to &quot;分支定界与整数规划&quot;">​</a></h1><div class="epigraph"><p>整数约束使顶点不必最优；松弛 LP 给界，分数变量分支，界差则剪枝。</p><footer>—— 据 Land and Doig, An Automatic Method of Solving Discrete Programming Problems, 1960；CLRS 第 34 章与标准 ILP 整理</footer></div><p>上一课<a href="/cs/lp-duality">LP 对偶</a>在连续多面体上强对偶。整数线性规划（ILP）：\\(x\\in\\mathbb{Z}\\)。NPC（含 0-1 背包判定、顶点覆盖）。缺口是分支定界：解 LP 松弛，对分数 \\(x_i\\) 分成 \\(\\le\\lfloor x_i\\rfloor\\) 与 \\(\\ge\\lceil x_i\\rceil\\)，用界剪掉。不重写单纯形。后课内点法仍连续。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>可行整数点是格点。松弛最优 \\(z_{LP}\\ge OPT\\)（最大化）。若松弛整数则结束。否则分支。全局上界用各叶松弛；下界用已知整数可行。\\(z_{LP}\\) 小于当前可行则剪。切割平面（Gomory）切掉分数顶点但留整数，可与分支合用（branch-and-cut）。</p><p>缺口是这棵搜索树，不是再证 NPC。</p><p><span class="marginnote">「LP 松弛」就是把「变量必须是整数」这条要求暂时忘掉，先解一个普通线性规划。比如 0-1 背包里某物品取 \\(x_i=0.6\\) 没有物理意义，但它给出一个信息：整数最优值不会超过这个分数解的目标值——这个上界正是后面剪枝的依据。</span></p><h3 id="松弛不是近似算法" tabindex="-1">松弛不是近似算法 <a class="header-anchor" href="#松弛不是近似算法" aria-label="Permalink to &quot;松弛不是近似算法&quot;">​</a></h3><p>\\(z_{LP}/OPT\\) 可以任意差（某些公式）。近似比后课。本课要精确最优，最坏指数。</p><p><span class="marginnote">Land–Doig 1960。Gomory 割。TSP 的 Held–Karp 松弛是著名 LP 界。后课内点走多面体内部，仍非整数。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>选变量分支（最分数、伪代价）。选结点：最佳界或深度。启发式找整数可行当全局下界。切平面可选。</p>',12)),(l(),i(s,null,{default:r(()=>[E(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20REL%5B%22LP%20%E6%9D%BE%E5%BC%9B%22%5D%20--%3E%20INT%5B%22%E6%95%B4%E6%95%B0%EF%BC%9F%22%5D%0A%20%20INT%20--%3E%7C%22%E6%98%AF%22%7C%20CAND%5B%22%E5%80%99%E9%80%89%E6%9C%80%E4%BC%98%22%5D%0A%20%20INT%20--%3E%7C%22%E5%90%A6%22%7C%20BR%5B%22%E5%88%86%E6%94%AF%20x_i%22%5D%0A%20%20BR%20--%3E%20REL%0A%20%20REL%20--%3E%20PRUNE%5B%22%E7%95%8C%E5%8A%A3%E5%88%99%E5%89%AA%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"对称性破坏、预处理很重要，本课点名。",-1)),a[4]||(a[4]=e("p",null,[e("span",{class:"marginnote"},"选结点顺序可以想象成考试策略：最佳界搜索像先做分值最高的题，尽快把下界抬高、多剪枝；深度优先像顺着一条路做到底，更快碰到整数可行解、内存也省。两者不改变正确性，只改变剪枝发生的早晚。")],-1)),a[5]||(a[5]=e("h2",{id:"机制",tabindex:"-1"},[n("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=e("p",null,"有限分支（变量有界时）故终止。正确性：最优在某叶。与 Held–Karp 子集 DP：那是固定状态；这里状态是约束分支，适合通用 ILP。与贪心：无保证。",-1)),a[7]||(a[7]=e("p",null,"下图回答一个具体问题：界值如何决定一棵子树是展开还是剪掉。",-1)),(l(),i(s,null,{default:r(()=>[E(o,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20ROOT%5B%22%E6%A0%B9%EF%BC%9Az_LP%20%3D%2014.5%22%5D%20--%3E%20A%5B%22%E5%AD%90%E6%A0%91%20A%EF%BC%9Az_LP%20%3D%2012.8%22%5D%0A%20%20ROOT%20--%3E%20B%5B%22%E5%AD%90%E6%A0%91%20B%EF%BC%9Az_LP%20%3D%2013.6%22%5D%0A%20%20B%20--%3E%20C%5B%22%E6%89%BE%E5%88%B0%E6%95%B4%E6%95%B0%E8%A7%A3%20z%20%3D%2013%22%5D%0A%20%20B%20--%3E%20D%5B%22%E5%AD%90%E6%A0%91%20C%EF%BC%9Az_LP%20%3D%2012.1%22%5D%0A%20%20A%20-.-%3E%7C%22%E4%B8%8A%E7%95%8C%2012.8%20%E4%BD%8E%E4%BA%8E%2013%22%7C%20CUT%5B%22%E6%95%B4%E6%A3%B5%E5%89%AA%E6%8E%89%22%5D%0A%20%20D%20-.-%3E%7C%22%E4%B8%8A%E7%95%8C%2012.1%20%E4%BD%8E%E4%BA%8E%2013%22%7C%20CUT%0A%20%20C%20--%3E%20BEST%5B%22%E8%BF%94%E5%9B%9E%E6%9C%80%E4%BC%98%2013%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=t('<p><span class="marginnote">常见误区：初学者容易担心被剪掉的子树里藏着更优解。实际上剪枝只在「子树的松弛上界都不超过当前已知整数解」时发生，上界性质保证子树内任何整数点的目标值都赢不过当前解，所以剪掉不会漏掉最优。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写求解器内部启发式全书。不写半定松弛。后课默认：ILP 精确用分支定界 + 松弛界。下一课内点法直觉（连续 LP）。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>整数使对偶间隙可能为正。</li><li>分支 + LP 界 + 剪枝 = 精确搜索。</li><li>最坏指数；实践靠界的质量。</li><li>出处：Land and Doig, 1960。</li></ul>',5))])}const b=d(B,[["render",P]]);export{c as __pageData,b as default};
